<?php require_once __DIR__ . '/includes/auth.php'; $user=require_role(['school_admin','principal','teacher','accountant']); $pdo=db(); check_tenant_active($pdo); $tid=require_tenant(); $base=''; $active='library'; $pageTitle='Library';

if(is_post()){ verify_csrf(); $a=$_POST['action']??'';
 if($a==='book'){ if(!empty($_POST['id'])) $pdo->prepare('UPDATE books SET title=?,author=?,isbn=?,category=?,copies_total=?,copies_available=? WHERE id=? AND tenant_id=?')->execute([trim($_POST['title']),trim($_POST['author']??''),trim($_POST['isbn']??''),trim($_POST['category']??''),(int)$_POST['copies_total'],(int)$_POST['copies_available'],(int)$_POST['id'],$tid]); else $pdo->prepare('INSERT INTO books(tenant_id,title,author,isbn,category,copies_total,copies_available) VALUES(?,?,?,?,?,?,?)')->execute([$tid,trim($_POST['title']),trim($_POST['author']??''),trim($_POST['isbn']??''),trim($_POST['category']??''),(int)($_POST['copies_total']??1),(int)($_POST['copies_total']??1)]); flash('success','Book saved.'); }
 elseif($a==='book_delete'){ $pdo->prepare('DELETE FROM books WHERE id=? AND tenant_id=?')->execute([(int)$_POST['id'],$tid]); flash('success','Book deleted.'); }
 elseif($a==='issue'){ $s=$pdo->prepare('SELECT copies_available FROM books WHERE id=? AND tenant_id=?'); $s->execute([(int)$_POST['book_id'],$tid]); if((int)$s->fetchColumn()>0){ $pdo->prepare('INSERT INTO book_issues(tenant_id,book_id,student_id,issue_date,due_date,status) VALUES(?,?,?,?,?,"issued")')->execute([$tid,(int)$_POST['book_id'],(int)$_POST['student_id'],date('Y-m-d'),$_POST['due_date']?:date('Y-m-d',strtotime('+14 days'))]); $pdo->prepare('UPDATE books SET copies_available=copies_available-1 WHERE id=?')->execute([(int)$_POST['book_id']]); flash('success','Book issued.'); } else flash('error','No copies available.'); }
 elseif($a==='return'){ $s=$pdo->prepare('SELECT * FROM book_issues WHERE id=? AND tenant_id=?'); $s->execute([(int)$_POST['id'],$tid]); $issue=$s->fetch();
   if($issue && $issue['status']==='issued'){ $late=max(0,(int)((strtotime(date('Y-m-d'))-strtotime($issue['due_date']))/86400)); $fine=round($late*0.50,2);
     $pdo->prepare('UPDATE book_issues SET return_date=CURDATE(),fine=?,status="returned" WHERE id=?')->execute([$fine,$issue['id']]); $pdo->prepare('UPDATE books SET copies_available=copies_available+1 WHERE id=?')->execute([$issue['book_id']]);
     flash('success','Book returned.'.($late>0?" Late by $late day(s) — fine ".money($fine).'.':' No fine.')); } }
 redirect('library.php'); }
$q=trim($_GET['q']??''); $s=$pdo->prepare('SELECT * FROM books WHERE tenant_id=? AND title LIKE ? ORDER BY id DESC'); $s->execute([$tid,"%$q%"]); $books=$s->fetchAll();
$students=$pdo->query("SELECT * FROM students WHERE tenant_id=$tid AND status='active' ORDER BY first_name")->fetchAll();
$s=$pdo->prepare('SELECT bi.*,b.title book_title,s.first_name,s.last_name FROM book_issues bi JOIN books b ON b.id=bi.book_id JOIN students s ON s.id=bi.student_id WHERE bi.tenant_id=? ORDER BY bi.id DESC LIMIT 50'); $s->execute([$tid]); $issues=$s->fetchAll();
$edit=null; if(!empty($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM books WHERE id=? AND tenant_id=?');$s->execute([(int)$_GET['edit'],$tid]);$edit=$s->fetch();}
include __DIR__ . '/includes/header.php'; ?>
