<div class="col-md-5"><select class="form-select" name="book_id" required><?php foreach($books as $b): ?><option value="<?= $b['id'] ?>"><?= e($b['title']) ?> (<?= $b['copies_available'] ?> avail.)</option><?php endforeach; ?></select></div>
